package org.slavicmyths.kalin;
import java.util.*;import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.server.level.*;import net.minecraft.world.entity.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.saveddata.SavedData;import net.minecraft.world.phys.Vec3;import org.slavicmyths.skim.HeroCalls;
/** Addressed jobs only; persists block rollback and progress, aborts active combat on restart. */
public final class KalinEncounter extends SavedData {
 public static final List<String> HEROES=List.of("ilya_muromets","dobrynya_nikitich","alyosha_popovich","finist");
 public enum Stage{BUILDING,ACTIVE,RESTORING}
 public static final class Cell{public final BlockPos pos;public final BlockState before,placed;public boolean applied;Cell(BlockPos p,BlockState a,BlockState b){pos=p;before=a;placed=b;}}
 public static final class Entry{public UUID id=UUID.randomUUID(),owner,boss;public String a,b;public UUID heroA,heroB;public Vec3 center;public Stage stage=Stage.BUILDING;public final List<Cell> cells=new ArrayList<>();public int cursor;public long outside,cleanupAt;public boolean credited;}
 public final Map<UUID,Entry> entries=new LinkedHashMap<>();public final Map<UUID,CompoundTag> progress=new HashMap<>();
 public static KalinEncounter get(ServerLevel w){return w.getServer().overworld().getDataStorage().computeIfAbsent(new Factory<>(KalinEncounter::new,KalinEncounter::load),"slavicmyths_kalin_175");}
 public Entry owner(UUID u){return entries.values().stream().filter(e->u.equals(e.owner)&&e.stage!=Stage.RESTORING).findFirst().orElse(null);}
 public boolean near(ServerLevel w,Vec3 p){return w.dimension()==Level.OVERWORLD&&entries.values().stream().anyMatch(e->Math.abs(p.x-e.center.x)<74&&Math.abs(p.z-e.center.z)<74);}
 public boolean nearBattle(ServerLevel w,Vec3 p){return w.dimension()==Level.OVERWORLD&&entries.values().stream().anyMatch(e->e.stage!=Stage.RESTORING&&p.distanceToSqr(e.center)<72*72);}
 public boolean active(UUID id){var e=entries.get(id);return e!=null&&e.stage==Stage.ACTIVE;}
 public static void message(ServerPlayer p,String key){p.sendSystemMessage(net.minecraft.network.chat.Component.translatable("message.slavicmyths.kalin_"+key));}
 public static boolean select(ServerPlayer p,String a,String b){if(!HEROES.contains(a)||!HEROES.contains(b)||a.equals(b)||HeroCalls.battleLocked(p))return false;if(!(HeroCalls.loaded(p,a) instanceof Mob h)||!(HeroCalls.loaded(p,b) instanceof Mob j)||h.level()!=p.level()||j.level()!=p.level())return false;p.getPersistentData().putString("KalinSelectA",a);p.getPersistentData().putString("KalinSelectB",b);p.playSound(KalinContent.sound("ui_select_two_heroes"),.6F,1);message(p,"selected");return true;}
 public static boolean start(ServerPlayer p){var w=p.serverLevel();var d=get(w);if(!p.isAlive()||p.isSpectator()||w.dimension()!=Level.OVERWORLD||HeroCalls.battleLocked(p)||d.near(w,p.position())){message(p,"busy");return false;}
 var chosen=new ArrayList<String>();for(var id:HEROES)if(HeroCalls.map(w,id).containsKey(p.getUUID()))chosen.add(id);if(chosen.size()!=2){message(p,"need_two_heroes");return false;}
 var requested=p.getPersistentData();if(requested.contains("KalinSelectA")&&(!chosen.contains(requested.getString("KalinSelectA"))||!chosen.contains(requested.getString("KalinSelectB")))){message(p,"need_two_heroes");return false;}
 var h=HeroCalls.loaded(p,chosen.get(0));var j=HeroCalls.loaded(p,chosen.get(1));if(!(h instanceof Mob x)||!(j instanceof Mob y)||!x.isAlive()||!y.isAlive()||x.level()!=w||y.level()!=w||x.distanceTo(p)>24||y.distanceTo(p)>24||x.getHealth()<=x.getMaxHealth()*.15||y.getHealth()<=y.getMaxHealth()*.15||KalinParty.recovering(x)||KalinParty.recovering(y)||x.getPersistentData().getBoolean("HeroRecalling")||y.getPersistentData().getBoolean("HeroRecalling")){message(p,"need_two_heroes");return false;}
 var center=p.blockPosition().offset(0,0,8);var plan=KalinCamp.blueprint(center);if(!suitable(p,center,plan)){message(p,"need_open_area");return false;}
 var e=new Entry();e.owner=p.getUUID();e.a=chosen.get(0);e.b=chosen.get(1);e.heroA=h.getUUID();e.heroB=j.getUUID();e.center=Vec3.atBottomCenterOf(center);for(var c:plan.entrySet())e.cells.add(new Cell(c.getKey(),w.getBlockState(c.getKey()),c.getValue()));d.entries.put(e.id,e);d.setDirty();message(p,"building");return true;}
 private static boolean openColumn(ServerLevel w,BlockPos q){if(!w.hasChunkAt(q)||!w.getWorldBorder().isWithinBounds(q)||!org.slavicmyths.sivka.SivkaWhistle.safeFloor(w,q.below()))return false;for(int y=0;y<5;y++){var at=q.above(y);var state=w.getBlockState(at);if(!w.getFluidState(at).isEmpty()||w.getBlockEntity(at)!=null||state.is(net.minecraft.world.level.block.Blocks.FIRE)||state.is(net.minecraft.world.level.block.Blocks.SOUL_FIRE)||state.is(net.minecraft.world.level.block.Blocks.WITHER_ROSE)||state.is(net.minecraft.world.level.block.Blocks.SWEET_BERRY_BUSH))return false;}return !w.getBlockCollisions(null,new net.minecraft.world.phys.AABB(q.getX(),q.getY(),q.getZ(),q.getX()+1,q.getY()+4.4,q.getZ()+1)).iterator().hasNext();}
 public static boolean suitable(ServerPlayer p,BlockPos c,Map<BlockPos,BlockState> plan){var w=p.serverLevel();for(int x=-32;x<=32;x++)for(int z=-32;z<=32;z++){var q=c.offset(x,0,z);if(!openColumn(w,q))return false;}for(var q:plan.keySet())if(!w.hasChunkAt(q)||!w.getWorldBorder().isWithinBounds(q)||!w.getBlockState(q).isAir()||!w.getFluidState(q).isEmpty()||w.getBlockEntity(q)!=null||!w.mayInteract(p,q))return false;return true;}
 /** Fence/iron-bar connection flags are computed by vanilla neighbor updates, not player edits. */
 private static boolean ownedState(BlockState actual,BlockState placed){if(actual.equals(placed))return true;if(actual.getBlock()!=placed.getBlock()||!(placed.getBlock() instanceof net.minecraft.world.level.block.FenceBlock||placed.getBlock() instanceof net.minecraft.world.level.block.IronBarsBlock))return false;for(var property:placed.getProperties()){String name=property.getName();if(name.equals("north")||name.equals("south")||name.equals("east")||name.equals("west"))continue;if(!actual.getValue(property).equals(placed.getValue(property)))return false;}return true;}
 public void tick(ServerLevel w){for(var e:new ArrayList<>(entries.values())){if(e.stage==Stage.RESTORING){if(w.getGameTime()<e.cleanupAt)continue;int budget=256;boolean waiting=false;for(var c:e.cells){if(!c.applied)continue;if(!w.hasChunkAt(c.pos)){waiting=true;continue;}if(budget--<=0){waiting=true;break;}if(ownedState(w.getBlockState(c.pos),c.placed))w.setBlock(c.pos,c.before,18);c.applied=false;setDirty();}if(!waiting){entries.remove(e.id);setDirty();}else if(budget==256)e.cleanupAt=w.getGameTime()+20;continue;}
 var p=w.getServer().getPlayerList().getPlayer(e.owner);if(p==null||!p.isAlive()||p.isSpectator()||p.serverLevel()!=w){finish(w,e,false);continue;}if(p.position().distanceToSqr(e.center)>48*48){if(e.outside==0)e.outside=w.getGameTime();if(w.getGameTime()-e.outside>=160){finish(w,e,false);continue;}}else e.outside=0;
 if(e.stage==Stage.BUILDING){int budget=256;while(budget-->0&&e.cursor<e.cells.size()){var c=e.cells.get(e.cursor++);if(!w.hasChunkAt(c.pos)||!w.getBlockState(c.pos).equals(c.before)||!w.mayInteract(p,c.pos)){finish(w,e,false);break;}c.applied=true;w.setBlock(c.pos,c.placed,2);setDirty();}if(e.stage==Stage.BUILDING&&e.cursor==e.cells.size()){var pos=e.center.add(0,0,-11);if(!HeroCalls.safeSpot(w,pos,1.8,4.4)){finish(w,e,false);continue;}var b=KalinContent.KALIN.get().create(w);b.owner=e.owner;b.encounter=e.id;b.center=e.center;b.moveTo(pos);e.boss=b.getUUID();e.stage=Stage.ACTIVE;if(!w.addFreshEntity(b)||!b.mount()){finish(w,e,false);continue;}b.begin(org.slavicmyths.finist.FalconAction.INTRO,60);var n=progress.computeIfAbsent(e.owner,k->new CompoundTag());n.putBoolean("kalin_battle_started",true);n.putString("selected_hero_a",e.a);n.putString("selected_hero_b",e.b);n.putLong("last_battle_timestamp",w.getGameTime());mirror(p,n);setDirty();w.playSound(null,BlockPos.containing(e.center),KalinContent.sound("encounter_start_fx"),net.minecraft.sounds.SoundSource.HOSTILE,.8F,1);w.playSound(null,BlockPos.containing(e.center.add(0,0,-20)),KalinContent.sound("banner_flap"),net.minecraft.sounds.SoundSource.BLOCKS,.4F,1);w.playSound(null,BlockPos.containing(e.center.add(-12,1,-14)),KalinContent.sound("camp_fire_loop_short"),net.minecraft.sounds.SoundSource.BLOCKS,.4F,1);message(p,"start");}}
 else if(w.getGameTime()%20==0&&!(w.getEntity(e.boss) instanceof KalinEntity)){finish(w,e,false);}}
 }
 private static void mirror(ServerPlayer p,CompoundTag n){p.getPersistentData().put("slavicmyths.kalin175",n.copy());}
 public void finish(ServerLevel w,Entry e,boolean win){if(e.stage==Stage.RESTORING)return;e.stage=Stage.RESTORING;e.cleanupAt=w.getGameTime()+(win?100:0);var p=w.getServer().getPlayerList().getPlayer(e.owner);if(win&&!e.credited&&p!=null&&p.isAlive()&&!p.isCreative()&&!p.isSpectator()&&p.serverLevel()==w&&p.position().distanceToSqr(e.center)<=48*48){e.credited=true;var n=progress.computeIfAbsent(e.owner,k->new CompoundTag());n.putBoolean("kalin_battle_won",true);n.putString("selected_hero_a",e.a);n.putString("selected_hero_b",e.b);n.putInt("times_kalin_defeated",n.getInt("times_kalin_defeated")+1);n.putBoolean("pending_reward_1_7_6",true);mirror(p,n);org.slavicmyths.rewards.RewardLedger.victory(p,4);message(p,"won");}
 if(e.boss!=null&&w.getEntity(e.boss) instanceof KalinEntity b){b.cleanup();if(!win)b.discard();}for(UUID id:List.of(e.heroA,e.heroB)){if(w.getEntity(id) instanceof Mob m){if(m.getPersistentData().getBoolean("KalinRetreated")&&m instanceof org.slavicmyths.marinka.DobrynyaEntity hero)hero.begin(org.slavicmyths.marinka.WitchAction.DRINK);m.getPersistentData().remove("KalinRetreated");m.setTarget(null);m.getNavigation().stop();}}setDirty();}
 @Override public CompoundTag save(CompoundTag n,HolderLookup.Provider lookup){var list=new ListTag();for(var e:entries.values()){var a=new CompoundTag();a.putUUID("Id",e.id);a.putUUID("Owner",e.owner);a.putUUID("HeroA",e.heroA);a.putUUID("HeroB",e.heroB);a.putString("A",e.a);a.putString("B",e.b);a.putLong("Center",BlockPos.containing(e.center).asLong());var cells=new ListTag();for(var c:e.cells)if(c.applied){var q=new CompoundTag();q.putLong("Pos",c.pos.asLong());q.put("Before",NbtUtils.writeBlockState(c.before));q.put("Placed",NbtUtils.writeBlockState(c.placed));cells.add(q);}a.put("Cells",cells);list.add(a);}n.put("Rollback",list);var ps=new CompoundTag();progress.forEach((id,p)->ps.put(id.toString(),p));n.put("Progress",ps);return n;}
 public static KalinEncounter load(CompoundTag n,HolderLookup.Provider lookup){var d=new KalinEncounter();var blocks=lookup.lookupOrThrow(net.minecraft.core.registries.Registries.BLOCK);for(var t:n.getList("Rollback",Tag.TAG_COMPOUND)){var a=(CompoundTag)t;var e=new Entry();e.id=a.getUUID("Id");e.owner=a.getUUID("Owner");e.heroA=a.getUUID("HeroA");e.heroB=a.getUUID("HeroB");e.a=a.getString("A");e.b=a.getString("B");e.center=Vec3.atBottomCenterOf(BlockPos.of(a.getLong("Center")));e.stage=Stage.RESTORING;for(var q:a.getList("Cells",Tag.TAG_COMPOUND)){var c=(CompoundTag)q;var cell=new Cell(BlockPos.of(c.getLong("Pos")),NbtUtils.readBlockState(blocks,c.getCompound("Before")),NbtUtils.readBlockState(blocks,c.getCompound("Placed")));cell.applied=true;e.cells.add(cell);}d.entries.put(e.id,e);}var ps=n.getCompound("Progress");for(var k:ps.getAllKeys())d.progress.put(UUID.fromString(k),ps.getCompound(k));d.setDirty();return d;}
}
